pack(21, "B2", T("Upper-intermediate 5: News & current events", "Trung cao cấp 5: Tin tức & thời sự"),
     T("Report what others said and discuss the news.", "Thuật lại lời người khác và bàn luận tin tức."),
 [lesson("reporting", T("Reporting what was said", "Thuật lại lời nói"), T("Pass on information accurately.", "Truyền đạt thông tin chính xác."), "radio", [
    ("Según el periódico, va a subir la gasolina.", "According to the newspaper, gas prices will rise.", "Theo báo, giá xăng sẽ tăng."),
    ("Dijeron que el metro estaría cerrado.", "They said the metro would be closed.", "Họ nói tàu điện ngầm sẽ đóng cửa."),
    ("El alcalde anunció que habrá nuevas ciclovías.", "The mayor announced there will be new bike lanes.", "Thị trưởng thông báo sẽ có làn xe đạp mới."),
    ("Se dice que mañana habrá protestas.", "They say there will be protests tomorrow.", "Nghe nói ngày mai sẽ có biểu tình."),
    ("Me contó que se había mudado.", "She told me she had moved.", "Cô ấy kể với tôi là đã chuyển nhà."),
    ("No está confirmado todavía.", "It isn't confirmed yet.", "Việc này vẫn chưa được xác nhận.")],
    focus=T("Reported speech shifts tenses: “va a cerrar” → dijo que iba a cerrar / estaría cerrado.", "Câu tường thuật lùi thì: “va a cerrar” → dijo que iba a cerrar / estaría cerrado.")),
  lesson("discussing", T("Discussing the news", "Bàn luận tin tức"), T("React and give a measured view.", "Phản hồi và nêu quan điểm chừng mực."), "message-square", [
    ("¿Viste lo que pasó con…?", "Did you see what happened with…?", "Bạn thấy chuyện xảy ra với… chưa?"),
    ("Es un tema bastante polémico.", "It's quite a controversial topic.", "Đó là chủ đề khá gây tranh cãi."),
    ("Hay que ver las dos caras de la moneda.", "You have to see both sides of the coin.", "Phải nhìn cả hai mặt của vấn đề."),
    ("Dudo que eso sea verdad.", "I doubt that's true.", "Tôi nghi ngờ điều đó là thật."),
    ("No me sorprende para nada.", "It doesn't surprise me at all.", "Tôi chẳng ngạc nhiên chút nào."),
    ("Habrá que esperar a ver qué pasa.", "We'll have to wait and see what happens.", "Phải chờ xem chuyện gì xảy ra."),
  ],
    focus=T("Doubt triggers the subjunctive: dudo que sea, no creo que tenga. Certainty doesn't: creo que es.", "Nghi ngờ đi với thức giả định: dudo que sea, no creo que tenga. Chắc chắn thì không: creo que es."))],
 [convo("news-chat", T("Chat about the news", "Tán gẫu về tin tức"), T("Pass on a headline and discuss it.", "Kể lại một tin và bàn luận."), "compass", [
    node("heard", "¿Escuchaste las noticias de hoy?", "Did you hear today's news?", "Bạn nghe tin hôm nay chưa?", "Report what you heard with “dijeron que…” or “según…”.", "Thuật lại bằng “dijeron que…” hoặc “según…”.",
      ok("metro", "Sí, dijeron que el metro estaría cerrado el domingo.", "Yes, they said the metro would be closed on Sunday.", "Rồi, họ nói Chủ Nhật tàu điện ngầm sẽ đóng cửa.", "¿En serio? ¿Por qué?", "Seriously? Why?", "Thật à? Sao vậy?", "why"),
      ok("bikes", "Según el periódico, habrá nuevas ciclovías en el centro.", "According to the paper, there'll be new bike lanes downtown.", "Theo báo, trung tâm sẽ có làn xe đạp mới.", "¡Ya era hora! ¿Y por qué ahora?", "About time! And why now?", "Cuối cùng cũng có! Sao giờ mới làm?", "why"),
      bad("direct", "El metro va a cerrar, dijo.", "The metro is going to close, he said.", "Tàu điện sẽ đóng cửa, anh ta nói.", "Sí, dijeron que el metro estaría cerrado el domingo.", "Ah, ¿dijeron que iba a cerrar? ¿Por qué?", "Ah, they said it would close? Why?", "À, họ nói nó sẽ đóng à? Sao vậy?", "why")),
    node("why", "¿Y por qué lo hacen?", "And why are they doing it?", "Thế sao họ lại làm vậy?", "Share what you know, or admit it's unconfirmed.", "Chia sẻ điều bạn biết, hoặc nói là chưa được xác nhận.",
      ok("works", "Se dice que es por obras, pero no está confirmado.", "They say it's for construction, but it's not confirmed.", "Nghe nói là do thi công, nhưng chưa xác nhận.", "Mmm, dudo que terminen a tiempo.", "Hmm, I doubt they'll finish on time.", "Ừm, mình nghi là họ không xong đúng hạn.", "opinion"),
      ok("traffic", "Para reducir el tráfico, según el gobierno.", "To reduce traffic, according to the government.", "Để giảm kẹt xe, theo chính quyền.", "No me sorprende. ¿Tú qué opinas?", "Doesn't surprise me. What do you think?", "Chẳng lạ. Bạn nghĩ sao?", "opinion"),
      bad("dunno", "No sé.", "I don't know.", "Không biết.", "Se dice que es por obras, pero no está confirmado.", "Bueno, ¿pero qué se dice?", "Well, but what are people saying?", "Thế người ta nói gì?", "opinion")),
    node("opinion", "¿Crees que va a funcionar?", "Do you think it'll work?", "Bạn nghĩ có hiệu quả không?", "Use “dudo que / no creo que + subjunctive” or “creo que + indicative”.", "Dùng “dudo que / no creo que + giả định” hoặc “creo que + trần thuật”.",
      ok("doubt", "No creo que funcione, pero habrá que esperar.", "I don't think it'll work, but we'll have to wait.", "Mình không nghĩ là hiệu quả, nhưng phải chờ xem.", "Pienso lo mismo.", "I think the same.", "Mình cũng nghĩ vậy."),
      ok("think", "Creo que sí, hay que ver las dos caras.", "I think so, you have to see both sides.", "Mình nghĩ là có, phải nhìn cả hai mặt.", "Puede ser. Ojalá tengas razón.", "Could be. I hope you're right.", "Có thể. Mong là bạn đúng."),
      bad("mood", "No creo que funciona.", "I don't think it works (wrong form).", "Mình không nghĩ là hiệu quả (sai dạng).", "No creo que funcione, pero habrá que esperar.", "“Que funcione”, ¿no? Pero sí, yo también lo dudo.", "“Que funcione”, right? But yes, I doubt it too.", "Phải là “que funcione” chứ? Nhưng đúng, mình cũng nghi lắm."))])])

